function drag(target,dx,dy,{cancel=false,escape=false}={}){const frame=target.closest('.desktop-panel'),b=frame.getBoundingClientRect(),edge=frame.dataset.edge;let {left:x,top:y,width,height}=target.getBoundingClientRect();x+=width/2;y+=height/2;if(target.classList.contains('desktop-panel-resizer')){if(['left','right'].includes(edge)){x=edge==='left'?b.right-2:b.left+2;y=b.top+b.height/2;}else{x=b.left+b.width/2;y=edge==='top'?b.bottom-2:b.top+2;}}pointer('pointerdown',target,x,y);pointer('pointermove',d,x+dx,y+dy);if(escape)d.dispatchEvent(new w.KeyboardEvent('keydown',{key:'Escape',bubbles:true,cancelable:true}));else pointer(cancel?'pointercancel':'pointerup',d,x+dx,y+dy);flush();}
