function reloadLayout(saved){const probe=new JSDOM('<!doctype html><body><main class="desktop-shell"></main></body>',{url:'https://panel-fixture.invalid/',runScripts:'outside-only',pretendToBeVisual:true});try{const v=probe.window,c=probe.getInternalVMContext();v.requestAnimationFrame=()=>0;v.cancelAnimationFrame=()=>{};v.setInterval=()=>0;v.getComputedStyle=el=>new Proxy(el.style,{get(t,k){return k==='getPropertyValue'?n=>t.getPropertyValue(n)||'0px':t[k]||'0px';}});for(const name of ['scheduleWindowTiling','queueDesktopStateBroadcast','syncNotifications','setWorkspaceInsets','setUniversalSearchOpen'])v[name]=()=>undefined;v.activeWorkspace='general';v.workspaceProfiles={general:{label:'General'}};v.localDisplaySlot=()=>1;v.activeDisplayRoster=()=>[{}];v.tileSession=()=>null;v.desktopPages={};v.contextMenuDescriptor=()=>null;v.localStorage.setItem('spatial-widget-panels-v1',saved);vm.runInContext(fs.readFileSync(path.join(root,'panel-widgets.js'),'utf8'),c);const r=new Map();for(const def of v.SpatialPanelWidgets.catalog.filter(item=>item.id!=='spacer')){const source=v.document.createElement('div');source.textContent=def.title;r.set(def.id,{source,nodes:[source],summary:()=>def.title});}v.SpatialPanelContent={create:()=>r};if(fs.existsSync(path.join(root,'panel-compact.js')))vm.runInContext(fs.readFileSync(path.join(root,'panel-compact.js'),'utf8'),c);vm.runInContext(fs.readFileSync(path.join(root,'panel-desktop.js'),'utf8'),c);return {state:JSON.parse(JSON.stringify(v.SpatialPanels.state())),popup:!!v.document.querySelector('.panel-applet-popup')};}finally{probe.window.close();}}
