test('lost pointer releases and hidden tabs abort panel and widget previews without saving',()=>{
 for(const kind of ['resize','panel','widget'])for(const cause of ['released','hidden']){
  P.edit(false);P.reset();const before=JSON.stringify(P.state()),saved=w.localStorage.getItem('spatial-widget-panels-v1'),draft=d.querySelector('#fixture-assistant-draft'),draftValue=draft.value;let x,y;
  if(kind==='resize'){const target=panel('panel-left').querySelector('.desktop-panel-resizer'),rect=panel('panel-left').getBoundingClientRect();x=rect.right+80;y=rect.top+rect.height/2;pointer('pointerdown',target,rect.right-2,y);}
  else if(kind==='panel'){startPanelDrag('panel-right');x=20;y=450;}
  else{P.edit(true);startWidgetDrag('assistant');const rect=widget('apps').getBoundingClientRect();x=rect.left+10;y=rect.top+1;}
  pointer('pointermove',d,x,y);assert(d.body.classList.contains('panel-is-dragging'),'A real '+kind+' preview starts');
  if(cause==='released')pointer('pointermove',d,x+20,y,1,0);
  else{Object.defineProperty(d,'hidden',{configurable:true,value:true});try{d.dispatchEvent(new w.Event('visibilitychange'));}finally{delete d.hidden;}}
  assert.equal(d.body.classList.contains('panel-is-dragging'),false,cause+' ends '+kind+' immediately');assert.equal(JSON.stringify(P.state()),before,'Aborted '+kind+' rolls back its preview');assert.equal(w.localStorage.getItem('spatial-widget-panels-v1'),saved,'Aborted preview is never persisted');
  assert.equal(d.querySelector('.panel-widget-drop-marker,.panel-drag-label,.is-drop-target,.desktop-widget.is-dragging'),null,'All transient drag UI is removed');assert.equal(d.querySelector('#fixture-assistant-draft'),draft);assert.equal(draft.value,draftValue);
  pointer('pointermove',d,x+80,y,1,0);pointer('pointerup',d,x+80,y);flush();assert.equal(JSON.stringify(P.state()),before,'Late mouse events cannot revive the aborted gesture');
 }
 P.edit(false);P.reset();
});
